args.ReplacementContent:
"            // Save to localStorage for dynamic telemetry tracking
            try {
                localStorage.setItem('rivenquant_config_ingest_' + asset, JSON.stringify(custom_config));
            } catch (e) {
                console.error("Error saving ingest params:", e);
            }

            // Close modal
            closeIngestConfig();

            // Run quick action with custom_config
            runQuickAction('run_job', {
                job: 'run_ingest',
                params: {
                    custom_config: custom_config
                }
            });"

